import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.InputStream;
import java.net.InetSocketAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;

/*
 * Library Book Reservation and Waiting Queue System
 * Java-only source: the web page HTML is generated by Java.
 * Uses an array to store books and a FIFO queue for each book's reservations.
 *
 * Run:
 *   javac LibrarySystemWeb.java
 *   java LibrarySystemWeb
 * Then open http://localhost:8080
 */
public class LibrarySystemWeb {
    static final Book[] books = new Book[100];
    static int bookCount = 0;
    static String message = "Welcome! Add a book or choose an action below.";

    static class Book {
        int id;
        String name;
        String author;
        boolean available = true;
        String issuedTo = "";
        Queue<String> waitingQueue = new LinkedList<>();

        Book(int id, String name, String author) {
            this.id = id;
            this.name = name;
            this.author = author;
        }
    }

    public static void main(String[] args) throws IOException {
        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
        HttpServer server = HttpServer.create(new InetSocketAddress("0.0.0.0", port), 0);
        server.createContext("/", LibrarySystemWeb::handleRequest);
        server.setExecutor(null);
        server.start();
        System.out.println("Library website is running on port " + port);
        System.out.println("Open http://localhost:" + port);
    }

    static void handleRequest(HttpExchange exchange) throws IOException {
        try {
            if ("POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                Map<String, String> form = readForm(exchange);
                processAction(form);
                exchange.getResponseHeaders().set("Location", "/");
                exchange.sendResponseHeaders(303, -1);
                return;
            }
            sendHtml(exchange, page());
        } catch (Exception ex) {
            message = "Something went wrong: " + escape(ex.getMessage() == null ? "Please check your input." : ex.getMessage());
            sendHtml(exchange, page());
        } finally {
            exchange.close();
        }
    }

    static Map<String, String> readForm(HttpExchange exchange) throws IOException {
        InputStream input = exchange.getRequestBody();
        String body = new String(input.readAllBytes(), StandardCharsets.UTF_8);
        Map<String, String> values = new LinkedHashMap<>();
        for (String pair : body.split("&")) {
            String[] parts = pair.split("=", 2);
            String key = URLDecoder.decode(parts[0], StandardCharsets.UTF_8);
            String value = parts.length > 1
                    ? URLDecoder.decode(parts[1], StandardCharsets.UTF_8) : "";
            values.put(key, value);
        }
        return values;
    }

    static void processAction(Map<String, String> f) {
        String action = f.getOrDefault("action", "");
        try {
            switch (action) {
                case "add": addBook(f); break;
                case "search": searchBook(f); break;
                case "issue": issueBook(f); break;
                case "return": returnBook(f); break;
                case "reserve": reserveBook(f); break;
                case "queue": showQueue(f); break;
                default: message = "Please choose a valid action.";
            }
        } catch (NumberFormatException e) {
            message = "Book ID must be a number.";
        }
    }

    static void addBook(Map<String, String> f) {
        if (bookCount == books.length) {
            message = "Book storage is full (maximum 100 books).";
            return;
        }
        int id = Integer.parseInt(f.getOrDefault("id", "").trim());
        if (findBook(id) != null) {
            message = "That Book ID already exists.";
            return;
        }
        String name = f.getOrDefault("name", "").trim();
        String author = f.getOrDefault("author", "").trim();
        if (name.isEmpty() || author.isEmpty()) {
            message = "Enter both the book name and author.";
            return;
        }
        books[bookCount++] = new Book(id, name, author);
        message = "Book added successfully: " + name;
    }

    static void searchBook(Map<String, String> f) {
        String query = f.getOrDefault("query", "").trim();
        if (query.isEmpty()) {
            message = "Enter a Book ID or book name to search.";
            return;
        }
        for (int i = 0; i < bookCount; i++) {
            Book b = books[i];
            if (String.valueOf(b.id).equalsIgnoreCase(query)
                    || b.name.toLowerCase().contains(query.toLowerCase())) {
                message = "Found: " + b.name + " (ID " + b.id + "), by " + b.author
                        + ". Status: " + (b.available ? "Available" : "Issued");
                return;
            }
        }
        message = "No book found for: " + query;
    }

    static void issueBook(Map<String, String> f) {
        Book b = requireBook(f);
        if (b == null) return;
        if (!b.available) {
            message = "This book is already issued. Reserve it to join the waiting queue.";
            return;
        }
        String student;
        if (!b.waitingQueue.isEmpty()) {
            student = b.waitingQueue.poll();
            message = "Book issued to the first waiting student: " + student + " (FIFO).";
        } else {
            student = f.getOrDefault("student", "").trim();
            if (student.isEmpty()) {
                message = "Enter the student name to issue this book.";
                return;
            }
            message = "Book issued successfully to " + student + ".";
        }
        b.available = false;
        b.issuedTo = student;
    }

    static void returnBook(Map<String, String> f) {
        Book b = requireBook(f);
        if (b == null) return;
        if (b.available) {
            message = "This book is not currently issued.";
            return;
        }
        String previousStudent = b.issuedTo;
        b.available = true;
        b.issuedTo = "";
        if (!b.waitingQueue.isEmpty()) {
            String nextStudent = b.waitingQueue.poll();
            b.available = false;
            b.issuedTo = nextStudent;
            message = "Book returned by " + previousStudent + " and automatically issued to " + nextStudent + " (FIFO).";
        } else {
            message = "Book returned successfully by " + previousStudent + ". It is now available.";
        }
    }

    static void reserveBook(Map<String, String> f) {
        Book b = requireBook(f);
        if (b == null) return;
        if (b.available && b.waitingQueue.isEmpty()) {
            message = "This book is available. You can issue it directly instead of reserving.";
            return;
        }
        String student = f.getOrDefault("student", "").trim();
        if (student.isEmpty()) {
            message = "Enter the student's name to reserve this book.";
            return;
        }
        if (b.issuedTo.equalsIgnoreCase(student) || b.waitingQueue.stream().anyMatch(s -> s.equalsIgnoreCase(student))) {
            message = student + " already has this book or is already waiting.";
            return;
        }
        b.waitingQueue.offer(student);
        message = student + " added to the waiting queue for \"" + b.name + "\".";
    }

    static void showQueue(Map<String, String> f) {
        Book b = requireBook(f);
        if (b == null) return;
        message = b.waitingQueue.isEmpty()
                ? "Waiting queue for \"" + b.name + "\" is empty."
                : "Waiting queue for \"" + b.name + "\": " + String.join(" → ", b.waitingQueue);
    }

    static Book requireBook(Map<String, String> f) {
        int id = Integer.parseInt(f.getOrDefault("id", "").trim());
        Book b = findBook(id);
        if (b == null) message = "Book ID " + id + " was not found.";
        return b;
    }

    static Book findBook(int id) {
        for (int i = 0; i < bookCount; i++) {
            if (books[i].id == id) return books[i];
        }
        return null;
    }

    static String page() {
        StringBuilder rows = new StringBuilder();
        for (int i = 0; i < bookCount; i++) {
            Book b = books[i];
            rows.append("<tr><td>").append(b.id).append("</td><td>")
                .append(escape(b.name)).append("</td><td>").append(escape(b.author))
                .append("</td><td><span class='badge ")
                .append(b.available ? "available" : "issued").append("'>")
                .append(b.available ? "Available" : "Issued to " + escape(b.issuedTo))
                .append("</span></td><td>").append(b.waitingQueue.size()).append("</td></tr>");
        }
        if (bookCount == 0) {
            rows.append("<tr><td colspan='5' class='empty'>No books added yet. Use “Add a book” to begin.</td></tr>");
        }

        return """
            <!doctype html>
            <html lang="en">
            <head>
              <meta charset="UTF-8">
              <meta name="viewport" content="width=device-width, initial-scale=1">
              <title>Library Book Reservation System</title>
              <style>
                body{font-family:Arial,sans-serif;background:#f3f6fb;color:#172033;margin:0}
                header{background:#172554;color:white;padding:28px 5%;box-shadow:0 3px 12px #0002}
                header h1{margin:0 0 8px;font-size:clamp(22px,4vw,32px)}
                header p{margin:0;color:#dbeafe}
                main{max-width:1100px;margin:25px auto;padding:0 16px}
                .notice{background:#e0f2fe;border-left:5px solid #0284c7;padding:14px 16px;border-radius:8px;margin-bottom:20px}
                .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}
                .card{background:white;border-radius:12px;padding:18px;box-shadow:0 4px 18px #17255412}
                h2{font-size:18px;margin:0 0 14px}
                label{display:block;font-size:13px;font-weight:bold;margin:10px 0 5px}
                input{box-sizing:border-box;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;font-size:14px}
                button{margin-top:13px;background:#2563eb;color:white;border:0;border-radius:7px;padding:10px 14px;font-weight:bold;cursor:pointer}
                button:hover{background:#1d4ed8}
                .table-wrap{overflow-x:auto;background:white;border-radius:12px;box-shadow:0 4px 18px #17255412;margin-top:20px}
                table{border-collapse:collapse;width:100%;min-width:650px}
                th,td{text-align:left;padding:12px 14px;border-bottom:1px solid #e5e7eb;font-size:14px}
                th{background:#eff6ff;color:#1e3a8a}
                .badge{display:inline-block;padding:5px 8px;border-radius:20px;font-size:12px}
                .available{background:#dcfce7;color:#166534}.issued{background:#fee2e2;color:#991b1b}
                .empty{text-align:center;color:#64748b;padding:24px}
                footer{text-align:center;color:#64748b;font-size:12px;padding:24px}
              </style>
            </head>
            <body>
              <header>
                <h1>📚 Library Book Reservation System</h1>
                <p>Manage books, issue and return records, reservations, and FIFO waiting queues.</p>
              </header>
              <main>
                <div class="notice"><strong>System message:</strong> %s</div>
                <div class="grid">
                  <section class="card">
                    <h2>➕ Add a book</h2>
                    <form method="post">
                      <input type="hidden" name="action" value="add">
                      <label>Book ID</label><input type="number" name="id" required>
                      <label>Book name</label><input name="name" required>
                      <label>Author</label><input name="author" required>
                      <button type="submit">Add book</button>
                    </form>
                  </section>
                  <section class="card">
                    <h2>🔍 Search a book</h2>
                    <form method="post">
                      <input type="hidden" name="action" value="search">
                      <label>Book ID or name</label><input name="query" required>
                      <button type="submit">Search</button>
                    </form>
                  </section>
                  <section class="card">
                    <h2>📖 Issue a book</h2>
                    <form method="post">
                      <input type="hidden" name="action" value="issue">
                      <label>Book ID</label><input type="number" name="id" required>
                      <label>Student name (if no one is waiting)</label><input name="student">
                      <button type="submit">Issue book</button>
                    </form>
                  </section>
                  <section class="card">
                    <h2>🔄 Return a book</h2>
                    <form method="post">
                      <input type="hidden" name="action" value="return">
                      <label>Book ID</label><input type="number" name="id" required>
                      <button type="submit">Return book</button>
                    </form>
                  </section>
                  <section class="card">
                    <h2>📝 Reserve a book</h2>
                    <form method="post">
                      <input type="hidden" name="action" value="reserve">
                      <label>Book ID</label><input type="number" name="id" required>
                      <label>Student name</label><input name="student" required>
                      <button type="submit">Reserve book</button>
                    </form>
                  </section>
                  <section class="card">
                    <h2>⏳ View waiting queue</h2>
                    <form method="post">
                      <input type="hidden" name="action" value="queue">
                      <label>Book ID</label><input type="number" name="id" required>
                      <button type="submit">Show queue</button>
                    </form>
                  </section>
                </div>
                <section class="table-wrap">
                  <table>
                    <thead><tr><th>Book ID</th><th>Book name</th><th>Author</th><th>Status</th><th>Waiting</th></tr></thead>
                    <tbody>%s</tbody>
                  </table>
                </section>
              </main>
              <footer>Java HTTP Server • Array-based book storage • Queue follows FIFO (First In, First Out)</footer>
            </body>
            </html>
            """.formatted(escape(message), rows);
    }

    static String escape(String value) {
        if (value == null) return "";
        return value.replace("&", "&amp;").replace("<", "&lt;")
                    .replace(">", "&gt;").replace("\"", "&quot;")
                    .replace("'", "&#39;");
    }

    static void sendHtml(HttpExchange exchange, String html) throws IOException {
        byte[] bytes = html.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "text/html; charset=UTF-8");
        exchange.sendResponseHeaders(200, bytes.length);
        exchange.getResponseBody().write(bytes);
    }
}
